    "solution": "import java.util.List;\nimport java.util.ArrayList;\n\nclass CartItem {\n    private String item;\n    private double price;\n    private int quantity;\n    public CartItem(String item, double price, int quantity) {\n        this.item = item;\n        this.price = price;\n        this.quantity = quantity;\n    }\n    public double getLineTotal() { return price * quantity; }\n}\n\nclass ShoppingCart {\n    private List<CartItem> items = new ArrayList<>();\n    public void addItem(String name, double price, int qty) {\n        items.add(new CartItem(name, price, qty));\n    }\n    public double calculateTotal() {\n        double sum = 0;\n        for (CartItem ci : items) sum += ci.getLineTotal();\n        return sum;\n    }\n}\n\nclass Main {\n    public static void main(String[] args) {\n        ShoppingCart cart = new ShoppingCart();\n        cart.addItem(\"Sut\", 11000.0, 2);\n        cart.addItem(\"Non\", 4000.0, 3);\n        System.out.println(\"Savatcha summasi: \" + cart.calculateTotal());\n    }\n}",
