    "solution": "import java.util.List;\nimport java.util.ArrayList;\nimport java.util.Map;\nimport java.util.LinkedHashMap;\n\nclass ShippingAddress {\n    private String street;\n    private String city;\n    public ShippingAddress(String street, String city) {\n        this.street = street;\n        this.city = city;\n    }\n    public String getStreet() { return street; }\n    public String getCity() { return city; }\n}\n\nclass Customer {\n    private String name;\n    private double accountBalance;\n    private ShippingAddress shippingAddress;\n    private Map<String, ShippingAddress> deliveryAddresses = new LinkedHashMap<>();\n\n    public Customer(String name, double accountBalance, ShippingAddress shippingAddress) {\n        this.name = name;\n        this.accountBalance = accountBalance;\n        this.shippingAddress = shippingAddress;\n    }\n\n    public String getName() { return name; }\n    public double getAccountBalance() { return accountBalance; }\n    public void setAccountBalance(double b) { this.accountBalance = b; }\n    public ShippingAddress getShippingAddress() { return shippingAddress; }\n    public void setShippingAddress(ShippingAddress a) { this.shippingAddress = a; }\n\n    public void addDeliveryAddress(String label, ShippingAddress a) {\n        deliveryAddresses.put(label, a);\n    }\n    public boolean useDeliveryAddress(String label) {\n        ShippingAddress a = deliveryAddresses.get(label);\n        if (a != null) {\n            this.shippingAddress = a;\n            return true;\n        }\n        return false;\n    }\n}\n\nclass OrderItem {\n    private String name;\n    private double unitPrice;\n    private int quantity;\n    public OrderItem(String name, double unitPrice, int quantity) {\n        this.name = name;\n        this.unitPrice = unitPrice;\n        this.quantity = quantity;\n    }\n    public double getLineTotal() { return unitPrice * quantity; }\n}\n\nclass Order {\n    private String orderId;\n    private Customer customer;\n    private double deliveryCost;\n    private List<OrderItem> items = new ArrayList<>();\n\n    public Order(String orderId, Customer customer) {\n        this(orderId, customer, 0.0);\n    }\n\n    public Order(String orderId, Customer customer, double deliveryCost) {\n        this.orderId = orderId;\n        this.customer = customer;\n        this.deliveryCost = deliveryCost;\n    }\n\n    public String getOrderId() { return orderId; }\n    public Customer getCustomer() { return customer; }\n\n    public void addItem(String name, double price, int qty) {\n        if (qty > 0) items.add(new OrderItem(name, price, qty));\n    }\n\n    public double getItemsTotal() {\n        double total = 0;\n        for (OrderItem item : items) total += item.getLineTotal();\n        return total;\n    }\n\n    public double getTotal() {\n        return getItemsTotal() + deliveryCost;\n    }\n\n    public void place() {\n        double total = getTotal();\n        customer.setAccountBalance(customer.getAccountBalance() - total);\n    }\n}\n\nclass Main {\n    public static void main(String[] args) {\n        ShippingAddress campus = new ShippingAddress(\"12 Istiqbol St\", \"Tashkent\");\n        Customer student = new Customer(\"00012345 Azizbek\", 950000.0, campus);\n        Order order = new Order(\"WIUT-CW2-FINAL\", student, 20000.0);\n        order.addItem(\"Java OOP Textbook\", 180000.0, 1);\n        order.addItem(\"Coursework Certification\", 150000.0, 1);\n        order.place();\n        System.out.println(\"CW2 Yakuniy buyurtma: \" + order.getOrderId() + \" | Talaba qoldig'i: \" + student.getAccountBalance() + \" | Jami to'langan: \" + order.getTotal());\n    }\n}",
